#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Node {
    int v;
    struct Node *l, *r;
} Node;

void serialize(Node* n, char* out) {
    if (!n) {
        strcat(out, "N,");
        return;
    }
    char buf[16];
    sprintf(buf, "%d,", n->v);
    strcat(out, buf);
    serialize(n->l, out);
    serialize(n->r, out);
}

Node* build(char** cursor) {
    char* token = strsep(cursor, ",");
    if (!token || token[0] == 'N') return NULL;
    Node* n = malloc(sizeof(Node));
    n->v = atoi(token);
    n->l = build(cursor);
    n->r = build(cursor);
    return n;
}

Node* deserialize(char* data) {
    char* cursor = data;
    return build(&cursor);
}

int main() {
    Node a = {1, NULL, NULL}, b = {2, NULL, NULL}, c = {3, NULL, NULL};
    a.l = &b;
    a.r = &c;
    char out[256] = "";
    serialize(&a, out);
    printf("%s\n", out);
    return 0;
}

